<script module lang="ts">
/**
 * Picks one value from a few options that are all visible (`design/components/radio.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/radio.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import * as zag from '@zag-js/radio-group'
import { useMachine } from '@zag-js/svelte'

import {
  agentMember,
  joinSlot,
  normalizeProps,
  roveRadio,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/radio-group.module.css'

export type RadioOrientation = NonNullable<RadioGroupProps['orientation']>

export interface RadioOption {
  value: string
  label: string
  disabled?: boolean
}

export interface RadioGroupProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField, because the group's question is the field's label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  onChange?: (value: string) => void
  options: RadioOption[]
  /**
   * Horizontal is for three short labels at most. Guidance, not enforcement.
   */
  orientation?: 'horizontal' | 'vertical'
  value?: string
}

export const controlKind = 'group'
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-label': ariaLabel,
  'aria-labelledby': ariaLabelledbyOwn,
  'aria-required': ariaRequiredOwn,
  defaultValue,
  disabled = false,
  id: idOwn,
  invalid: invalidOwn = false,
  name,
  onChange,
  options,
  orientation = 'vertical',
  value,
}: RadioGroupProps = $props()
const uid = $props.id()
const joined = joinSlot(controlKind, () => ({ disabled: disabled, name: name }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const ariaRequired = $derived(
  joined.passed['aria-required'] === undefined
    ? ariaRequiredOwn
    : (joined.passed['aria-required'] as typeof ariaRequiredOwn),
)
const id = $derived(
  joined.passed['id'] === undefined ? idOwn : (joined.passed['id'] as typeof idOwn),
)
const invalid = $derived(
  joined.passed['invalid'] === undefined
    ? invalidOwn
    : (joined.passed['invalid'] as typeof invalidOwn),
)
let group = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      value: value,
      defaultValue: defaultValue,
      disabled: disabled,
      name: name,
      orientation: orientation,
      onValueChange: (details) => {
        onChange?.(details.value ?? '')
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const stop = $derived(
  api.value ?? options.find((option) => !(disabled || option.disabled === true))?.value,
)
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = agentMember({
    member: 'RadioGroup',
    element: () => group,
    state: () => ({
      value: api.value ?? null,
      options: options.map((option) => ({
        id: option.value,
        label: option.label,
        ...(option.disabled === true ? { disabled: true } : {}),
      })),
      disabled: disabled,
      invalid: invalid,
    }),
    actions: {
      choose: { argument: 'id', run: (value) => value !== api.value && api.setValue(value) },
    },
  })
  release1 = () => {
    ran()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={group}
    class={styles.group}
    role="radiogroup"
    {id}
    aria-label={ariaLabel}
    aria-labelledby={ariaLabelledby}
    aria-describedby={ariaDescribedby}
    aria-required={ariaRequired}
    aria-invalid={(invalid) ? true : undefined}
    data-orientation={orientation}
    data-disabled={(disabled) ? '' : undefined}
    data-invalid={(invalid) ? '' : undefined}
    data-required={(ariaRequired) ? '' : undefined}
    data-member="radio-group"
    >{#each options as option (option.value)
      }<label class={styles.row}
        ><button
          class={styles.circle}
          type="button"
          role="radio"
          value={option.value}
          aria-checked={api.value === option.value}
          disabled={disabled || option.disabled === true}
          tabindex={(option.value === stop ? 0 : -1) as never}
          data-state={(api.value === option.value) ? 'checked' : 'unchecked'}
          data-disabled={(disabled || option.disabled === true) ? '' : undefined}
          onclick={() => { api.setValue(option.value) }}
          onkeydown={(event) => { event.key === 'Enter' ? event.preventDefault() : roveRadio(event, (next) => api.setValue(next)) }}
          >{#if api.value === option.value}<span class={styles.dot} data-state="checked"></span>{/if
        }</button
        ><span class={styles.label}>{option.label}</span
      ></label
    >{/each
  }</div
  >{#if name !== undefined}<input type="hidden" {name} value={api.value ?? ''} {disabled} />{/if
}{/if
}{@render joined.end?.()}
